insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('06ed0b9c-9f05-431e-9497-92b0c1c24c97', 2, 'El primer párrafo define la palabra: cuando el jugador le pega a la bola, a eso se le llama «stroke». Ni dar instrucciones ni tomar un hoyo aparecen como parte de esa definición.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
