insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6853cfc5-f477-4fa7-8a2d-53d75f6bf107', 0, 'El texto dice que las primeras formas del golf se jugaron en los Países Bajos «and then in Scotland»: ese «then» ordena los dos lugares y deja a Escocia en segundo lugar. Estados Unidos aparece después, con el primer campo en una finca de Illinois.');

