insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d5802e95-1262-49d2-b4a4-821fba76176c', 2, 'Los primeros campos eran praderas y las ovejas se comían el pasto para mantenerlo corto. Illinois se menciona por el primer campo estadounidense, no por el pasto, y ninguna empresa aparece en el texto.');

