insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3cd1b412-c0e3-49b8-830a-a8e9c41709cc', 0, 'El texto dice que los jugadores británicos como John Taylor fueron considerados los mejores en el siglo XIX. Palmer y Nicklaus aparecen en un renglón distinto, ya en los años sesenta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3dae06fd-5901-467b-8db2-6e1316fb3379', 'ing',
