  'c164c4d9-ced9-4996-a11c-f0c7fcaedb9b', 'Parte 5 · Comprensión de lectura',
  'If golfers want the balls to go further, they need a special',
  array['leather.', 'club.', 'field.'],
  'La palabra further apunta a distancia. Busca en el texto la frase que hable de «how far» y ahí está la respuesta.', 'publicada', 'modelo', '350ec38b8138121d3a0ab65add0d5e4b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3dae06fd-5901-467b-8db2-6e1316fb3379', 1, 'El tercer párrafo explica que los golfistas eligen entre distintos palos según qué tan lejos quieran mandar la bola: la distancia depende del palo. El cuero fue material de las bolas antiguas y el campo es el lugar donde se juega.');

