insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1ed6291e-4263-4dfe-b6e7-7cee63fca52c', 0, 'El texto cierra ese párrafo diciendo que la tecnología avanzada del diseño de las bolas modernas «has improved the game a lot»: mejoró el juego. El cuero es del siglo XVII, y que las bolas lleguen más lejos no se afirma en ninguna parte.');

