insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2714aa6f-d49e-4c43-afb4-2d0718081758', 1, 'La última frase es la clave: gana quien tenga el menor número de golpes en todos los hoyos. Menos golpes es exactamente pegarle menos veces a la bola.');

