insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b47780c2-dbfa-4221-9486-0de82b8ae342', 2, 'Nació en Kansas, pero la familia se mudó a Texas y allí fue donde creció junto a su hermana menor. California solo aparece como el origen de la mamá.');

