  array['David.', 'Helen.', 'Jim.'],
  'Cuando el texto presenta varios familiares, anota al lado de cada nombre qué hace: así no los confundes al responder.', 'publicada', 'modelo', 'c5129af1053f46a84be60dbdbd2b9e95';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b24db1c8-1a1a-4828-b98b-12ac62b5379d', 2, 'Fue el tío Jim, mecánico, quien la llevó a la feria y quien se subió con ella al avión. David es el papá, dueño de una empresa, y Helen es la hermana pintora.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4274d57b-574b-488b-a02f-6e6e47f6a30a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'd5bd572e-d434-44cf-876e-22ac48635e1f', 'Parte 5 · Comprensión de lectura',
  'The first time Evelyn got on a plane, she was the',
  array['pilot.', 'passenger.', 'mechanic.'],
  'Fíjate en quién hace la acción: «he flew it while she watched» deja claro quién manejaba y quién no.', 'publicada', 'modelo', 'fc8e1b34fa75f124ccb543b4b82fc9f8';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4274d57b-574b-488b-a02f-6e6e47f6a30a', 1, 'El texto dice que él pilotaba el avión mientras ella lo observaba: iba de pasajera. Piloto llegó a ser después, y el mecánico era el tío.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '47d127ef-e89f-47f1-8389-b8cb1f6bbe90', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'd5bd572e-d434-44cf-876e-22ac48635e1f', 'Parte 5 · Comprensión de lectura',
  'What occupation did she have while being in a foreign country?',
  array['pharmacist', 'student', 'musician'],
  'Cuando preguntan por «a foreign country», primero identifica cuál país no es el suyo y solo después busca qué hacía allí.', 'publicada', 'modelo', '792282ccf02aca1b401d985a1a6d9c8b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('47d127ef-e89f-47f1-8389-b8cb1f6bbe90', 0, 'El único país extranjero que visita es Canadá, y allí ayudaba a vender medicinas para los enfermos: eso es trabajo de farmacia. Estudiante lo fue en Filadelfia, que queda en su propio país, y la música era lo del primo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '09dd033a-25a3-4362-8f2f-1378b8e0ad66', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'd5bd572e-d434-44cf-876e-22ac48635e1f', 'Parte 5 · Comprensión de lectura',
  'Where was she taught to fly a plane?',
  array['in Philadelphia', 'in Toronto', 'in Sacramento'],
  'Cada ciudad del texto trae asociada una actividad distinta. Empareja ciudad y actividad antes de escoger.', 'publicada', 'modelo', '610bf87cf59fa37bafb463b91132263c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('09dd033a-25a3-4362-8f2f-1378b8e0ad66', 2, 'Aprendió a volar en Sacramento, junto a su primo. En Filadelfia entró a la escuela de medicina y en Toronto vendía medicinas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '8b974360-448d-44ec-98ac-a5b14d8f9a91', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'd5bd572e-d434-44cf-876e-22ac48635e1f', 'Parte 5 · Comprensión de lectura',
  'To get her plane, she borrowed cash from one of her',
  array['parents', 'friends', 'cousins'],
  'El verbo lend significa prestar. Búscalo en el texto y al lado estará quién prestó el dinero.', 'publicada', 'modelo', 'c5bd8bff066677b7a740658c26ad924e';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8b974360-448d-44ec-98ac-a5b14d8f9a91', 0, 'El texto dice que compró el avión gracias al dinero que le prestó uno de sus padres. La mejor amiga aparece después, ayudándola a conseguir trabajo, y el primo solo la acompaña en el entrenamiento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '52d70b62-2fca-453a-8da8-d592144215f7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'd5bd572e-d434-44cf-876e-22ac48635e1f', 'Parte 5 · Comprensión de lectura',
  'Based on the text, Evelyn''s life was full of',
  array['adventure.', 'accidents.', 'art.'],
  'Las preguntas que empiezan con «Based on the text» piden una conclusión general: mira el conjunto, no un solo renglón.', 'publicada', 'modelo', '5e2ab11e664b4352240aa58865105453';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('52d70b62-2fca-453a-8da8-d592144215f7', 0, 'Toda su vida es una sucesión de viajes, mudanzas y riesgos: aprender a volar, comprar un avión y cruzar el océano. Accidentes solo hay uno, y ella lo vio de lejos; el arte es lo de su hermana pintora.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e1c16bfc-f1b1-4deb-866f-3ced95d3ec74', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'What is the writer doing in this article?',
  array['convincing people to stop using all Internet apps.', 'teaching readers how to use different internet apps.', 'encouraging people to use some social media in a different way.', 'showing readers how important it was media.'],
  'Para la intención del autor, mira cómo cierra el texto: si termina celebrando su decisión, está invitándote a tomarla.', 'publicada', 'modelo', '37abf601b50460d897ba2fe96c2e5779';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e1c16bfc-f1b1-4deb-866f-3ced95d3ec74', 0, 'El autor cuenta que dejó las redes y dedica el texto entero a mostrar lo bien que le fue: más trabajo, invitaciones genuinas, amistades reales, sentirse libre. Ese recuento sirve para convencer a otros de hacer lo mismo. No enseña a usar aplicaciones ni propone usarlas de otra forma, porque él las abandonó por completo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f1203c92-9825-4a6a-804f-5290b83002f7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'What can a reader find out from this text?',
  array['what benefits leaving social media provides.', 'how to avoid using your e-mail account all the time.', 'when people depend too much on the Internet.', 'which types of people are more likely to use social media.'],
  'Pregúntate qué se lleva el lector al terminar. Si todo el texto apunta a lo mismo, esa es la respuesta.', 'publicada', 'modelo', '8d97ab7c742170c4a4b018f955cc2944';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f1203c92-9825-4a6a-804f-5290b83002f7', 0, 'El texto es una lista de ventajas: rinde más, recibe invitaciones sinceras, se relaciona cara a cara y disfruta sin pensar en publicarlo. El correo lo menciona como algo que ahora sí alcanza a responder, no como un problema, y nunca clasifica tipos de personas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9618e15e-e86d-4050-bbb0-1e6f7332a45f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'After quitting social media, the writer',
  array['has been working more.', 'still receives many invitations.', 'has more friends in his social networks.', 'is learning more about his business.'],
  'Cuando una opción usa palabras del texto pero cambia la cantidad (many, more, less), vuelve a leer esa frase completa.', 'publicada', 'modelo', '4c890308ac0dc4d9995e0874fbeabe22';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9618e15e-e86d-4050-bbb0-1e6f7332a45f', 0, 'Dice que ahora saca adelante más trabajo y le alcanza el tiempo para tareas extra. Sobre las invitaciones aclara lo contrario: recibe menos, aunque más sinceras. Y ya no tiene redes, así que no puede tener más amigos en ellas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'b01c2906-75ef-43b1-8065-dfd437a79b1f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'What was different when the writer used Facebook, Twitter, and Instagram?',
  array['the number of close friends that he had.', 'the way he cared about his health issues.', 'the types of relationships he used to have.', 'the time of the day he went out with friends.'],
  'Distingue cambios de cantidad (cuántos) de cambios de tipo (cómo son). Aquí lo que cambió fue el cómo.', 'publicada', 'modelo', '7fa15111a65b019457f1ab1a97892955';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b01c2906-75ef-43b1-8065-dfd437a79b1f', 2, 'El cambio que describe es de calidad, no de cantidad: antes seguía a todo el mundo sin enterarse de nada; ahora se involucra de verdad, cara a cara y sin mirar el celular. Los amigos que le importan siguen siendo los mismos, así que el número no cambió.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '678bc34f-ea3a-4d10-9775-f1d81e89d5b3', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'Which of these sentences would the writer most likely say?',
  array['Used social networks more, daily.', 'You must learn how to have more friends online.', 'I won''t go back to Facebook.', 'I won''t get health issues anymore.'],
  'Para «what would the writer say», escoge la frase que podría ir al final del texto sin contradecir nada de lo anterior.', 'publicada', 'modelo', '46e5b110fb93d919e3e3afe5377aaf76';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('678bc34f-ea3a-4d10-9775-f1d81e89d5b3', 2, 'Cierra diciendo que se siente libre y que disfruta algo que no sabía que había perdido: alguien así no piensa volver. Aumentar el uso o buscar más amigos en línea va en contra de todo el texto, y él nunca promete que no tendrá problemas de salud.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6727de16-3f52-4f06-8c17-962e7126178f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'Which of these statements wouldn''t the writer say?',
  array['I miss social media a little bit.', 'I would like my friends to read my experience.', 'I felt much better before, when I had social media.', 'My life is now more real and less virtual.'],
  'En las preguntas con wouldn’t o not, la respuesta es la que choca con el texto. Marca la palabra negativa antes de leer las opciones.', 'publicada', 'modelo', 'ce403ebe178c80fe8a24805a805f1a1c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6727de16-3f52-4f06-8c17-962e7126178f', 2, 'Decir que estaba mucho mejor antes contradice de frente el cierre del texto, donde afirma sentirse libre y disfrutar algo que había perdido. Las otras tres encajan con alguien contento con su decisión y orgulloso de contarla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '946001d1-ff07-4ad6-90c8-02274ee39368', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf883c0c-09ee-4604-9611-bde45b2e0e55', 'Parte 5 · Comprensión de lectura',
  'According to the text, what is not an advantage of quitting social media?',
  array['Having more time for working and business.', 'Interacting with people face to face.', 'Enjoying unexpected experiences.', 'Watching more videos and photos of daily activities.'],
  'En las preguntas con «not», tres opciones son correctas y una sobra. Busca la que describa el pasado, no el presente.', 'publicada', 'modelo', 'e68e35f477e685a1b89835d397aab890';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('946001d1-ff07-4ad6-90c8-02274ee39368', 3, 'Ver videos y fotos del día a día es justo lo que hacía antes, y el propio texto lo llama un hábito horrible, casi una enfermedad: es lo que dejó, no lo que ganó. Las otras tres sí aparecen como ventajas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4174ed53-2e1a-470a-9f76-e8ee9fe0052b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd42b27b-8da3-4449-9652-79c89943f7d4', 'Parte 5 · Comprensión de lectura',
  'What is the writer''s purpose in the article?',
  array['describe Bogotá in a detailed manner.', 'talk about Chía''s food and people.', 'tell the reader about his trip to Bogotá and Chía.', 'recommend Colombian museums and food'],
  'El título suele delatar el propósito. Aquí anuncia un viaje a Bogotá «y otros lugares», y eso es lo que cuenta.', 'publicada', 'modelo', '4c9ab0aa5ba7584b7cec8cc494984a77';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4174ed53-2e1a-470a-9f76-e8ee9fe0052b', 2, 'El texto es un relato de viaje: llega a Bogotá, visita el museo, se queda con una familia en Chía y termina en un restaurante. Describe momentos de un recorrido, no la ciudad en detalle ni únicamente la comida.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'dad6c47a-709e-4dd2-bc4a-dc30ca6cf6f0', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd42b27b-8da3-4449-9652-79c89943f7d4', 'Parte 5 · Comprensión de lectura',
  'What attitude does the writer show in the text?',
  array['A place is really boring when it rains.', 'Other things are more important than money.', 'Food must always be well prepared.', 'Museums are the best places in the world.'],
  'La actitud del autor aparece donde opina, no donde narra. Busca las frases con «I think», «I wonder» o preguntas retóricas.', 'publicada', 'modelo', 'd9ec8ebee7cfe24b47e6c854934e0502';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dad6c47a-709e-4dd2-bc4a-dc30ca6cf6f0', 1, 'Al hablar del oro se pregunta por qué la gente ama tanto el dinero, dice que es apenas un metal y remata preguntando de qué sirve al morir. Eso es poner otras cosas por encima del dinero. La lluvia lo incomoda, pero no dice que el lugar sea aburrido.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3a307ec2-285b-4ad8-a734-368af9e6cb6b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd42b27b-8da3-4449-9652-79c89943f7d4', 'Parte 5 · Comprensión de lectura',
  'What''s the writer''s opinion about gold?',
  array['ancient cultures used it a lot because of their customs.', 'it will be very valuable when you die.', 'you can wear it on your clothes all the time.', 'people should not consider it important.'],
  'Cuando preguntan por la opinión, descarta todo lo que sea un hecho contado, aunque esté en el texto.', 'publicada', 'modelo', 'a301008de610f54be16bf3478c623a15';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3a307ec2-285b-4ad8-a734-368af9e6cb6b', 3, 'Su opinión es que el oro no tiene nada de especial, que es solo un metal: eso es decir que no debería dársele tanta importancia. Que los antiguos lo usaran en ritos es un dato del texto, no una opinión suya.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c6e5c998-f31e-4ad8-aec4-b24c66494bec', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd42b27b-8da3-4449-9652-79c89943f7d4', 'Parte 5 · Comprensión de lectura',
  'What does the writer think about the family''s houses in Chía?',
  array['They were made in an unorganized but nice way.', 'They were constructed with no order at all.', 'Everybody likes to live near their family in Chía.', 'Everybody lives next to each other because there''s no space.'],
  'Cuando una frase tiene «but», la idea completa está en los dos lados. Una opción que solo recoge uno se queda corta.', 'publicada', 'modelo', '5fee8259f2cf0c727e2c3559d30f6437';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c6e5c998-f31e-4ad8-aec4-b24c66494bec', 0, 'Dice que las casas son viejas y mal diseñadas, hechas por ellos mismos en estilos distintos, «pero todas hermosas y asombrosas». Ese «pero» junta las dos ideas: desordenadas y a la vez bonitas. Que no haya orden en absoluto se queda con la mitad de la frase.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '40fc7b22-e002-46a8-a062-cb1f72acadd9', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd42b27b-8da3-4449-9652-79c89943f7d4', 'Parte 5 · Comprensión de lectura',
  'Which of these ideas shows the writer''s opinion?',
  array['Lots of people in Colombia need gold to build bigger and more modern houses.', 'Colombian people are very kind and like being together with their family.', 'Most restaurants and houses in Colombia serve very good, cheap food.', 'Colombian museums are interesting because they keep gold used in the past.'],
  'Antes de escoger, revisa que cada palabra de la opción tenga respaldo. Una sola palabra inventada (como «cheap») la descarta.', 'publicada', 'modelo', 'e90c2302c8c22c3d94432e300503bed3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('40fc7b22-e002-46a8-a062-cb1f72acadd9', 1, 'Una familia que acaba de conocer lo invita a quedarse, y él dice que nunca en su vida había visto un sentido de familia tan bonito: eso es exactamente gente amable a la que le gusta estar junta. El texto nunca habla de precios ni dice que se necesite oro para construir.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3d1d4b74-9842-476b-9f81-5da609eabdc9', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'A different type of bread was first used in a hamburger in',
  array['Ohio.', 'Texas.', 'Connecticut.'],
  'Cuando varias descripciones se parecen, subraya la palabra que cambia en una sola de ellas: ahí está la diferencia.', 'publicada', 'modelo', '73ad0a4bf2131db5ddc219476411959b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3d1d4b74-9842-476b-9f81-5da609eabdc9', 2, 'Tres de los posibles inventores usaron «soft bread»; el único que cambió el pan fue Louis Lassen, de Connecticut, que sirvió la carne entre dos tajadas de tostada. Ohio es de Menches y Texas de Fletcher David, ambos con pan blando.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '5805d5a5-8e4f-4e22-bdf1-a833b696c3ef', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'The hamburger became known by people from all over the world in',
  array['1885.', '1900.', '1904.'],
  'La expresión «all over the world» pide un evento internacional. Búscalo en el texto: aquí es la world exhibition.', 'publicada', 'modelo', '9995b82edc1f7febd25e2de25f5556fb';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5805d5a5-8e4f-4e22-bdf1-a833b696c3ef', 2, 'En 1904 se vendió en una exposición mundial y fue allí donde recibió el nombre de «hamburger». Una exposición mundial es justamente donde llega gente de todo el planeta. Las otras dos fechas corresponden a ventas locales.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9998f664-8d8c-42dd-bc08-0c9379425cba', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'Who made a Hamburger, with meat prepared in a special way?',
  array['Charlie Nagreen', 'Louis Lassen', 'Fletcher David'],
  'Compara cómo describe el texto la carne de cada uno: pieces y meat sandwich son formas simples; meatballs implica preparación.', 'publicada', 'modelo', '55eed25fdae69ad50cf263c3a518949d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9998f664-8d8c-42dd-bc08-0c9379425cba', 0, 'Nagreen vendía albóndigas entre dos panes: convertir la carne en albóndigas es prepararla de una forma particular. Lassen usó trozos de carne sin más y Fletcher David un sándwich de carne corriente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'd1f7a2d0-5f77-441e-8b68-4736442754c2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'Hamburgers in Germany were different from the American ones in that they',
  array['were very popular.', 'had more meat.', 'were known later.'],
  'Popular equivale a common o usual. Si no encuentras la palabra exacta, busca un sinónimo en el texto.', 'publicada', 'modelo', '888605792b6355829f28b426301b59e9';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d1f7a2d0-5f77-441e-8b68-4736442754c2', 0, 'En Hamburgo la carne con pan «was more common» y «was a usual dish»: era el plato de todos los días, muy popular. El texto nunca compara cantidades de carne, y en Alemania se conoció antes, no después.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '04cb2eb7-a4eb-4414-af13-7cde0ec219df', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'The hamburgers brought from Germany to the US were',
  array['hard to find.', 'interesting to make.', 'easy to eat.'],
  'Poder comer algo de pie o caminando es la definición práctica de «easy to eat». Traduce la escena, no solo las palabras.', 'publicada', 'modelo', '642551514c02388cc9039acb1f036771';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('04cb2eb7-a4eb-4414-af13-7cde0ec219df', 2, 'El texto dice que cualquiera podía prepararla y que se comía de pie o caminando: eso es comida fácil de comer. Que fuera un plato usual descarta que fuera difícil de conseguir.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'fe6a5dd6-4c1b-44d5-a8a8-5a54ac23fac7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'At the beginning of the last century, some people ate hamburgers for',
  array['breakfast.', 'lunch.', 'dinner.'],
  'Midday es mediodía. Ubica la palabra de la hora en el texto y tradúcela a la comida que corresponde.', 'publicada', 'modelo', '7ff705f266d45bbee2656a5ec3372892';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fe6a5dd6-4c1b-44d5-a8a8-5a54ac23fac7', 1, 'A comienzos del siglo XX era comida de obreros y se servía en restaurantes cerca de las fábricas «at midday»: al mediodía, es decir, el almuerzo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '62cb5f45-9593-494b-8d35-7a2a37802067', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '906af6e1-d767-4a0c-ae68-8d4c9e55e79b', 'Parte 5 · Comprensión de lectura',
  'What changed the way people thought of the hamburger in 1920?',
  array['a new path.', 'new job.', 'a new machine.'],
  'Si la opción no usa la palabra del texto, tradúcela a una categoría: un automóvil es, ante todo, una máquina.', 'publicada', 'modelo', '4e4edbdd2c7fc8b851bc08b92be3d392';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('62cb5f45-9593-494b-8d35-7a2a37802067', 2, 'Lo que cambió su reputación fue la llegada del automóvil al mercado y el deseo de comer en la carretera. El automóvil es una máquina nueva; el texto no menciona caminos nuevos ni empleos nuevos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9a8ab27d-bd0d-4ab6-b1af-d508b4a23181', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'f5575687-b32e-46e0-ad64-7b8c9ce7bada', 'Parte 5 · Comprensión de lectura',
  'What is the writer trying to do in this text?',
  array['advertise the best London Fashion Week', 'describe the routine she follows while getting dressed', 'advise about the right colors to wear', 'show that fashion is unnecessary for success'],
  'La intención suele estar en el último párrafo. Léelo primero cuando pregunten «what is the writer trying to do».', 'publicada', 'modelo', '65f8ebd879a133cc3700bfeb83f1d594';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9a8ab27d-bd0d-4ab6-b1af-d508b4a23181', 3, 'Todo el texto lleva al cierre: el éxito es un estado mental y decide no prestarle atención a la semana de la moda. La rutina de vestirse es el ejemplo con el que llega a esa conclusión, no el tema.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'de9d8020-d261-4375-9161-4bcdcd2ae192', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'f5575687-b32e-46e0-ad64-7b8c9ce7bada', 'Parte 5 · Comprensión de lectura',
  'In this letter, the reader can find',
  array['the right clothing for very cold days.', 'what will be in fashion each season.', 'who the model of the moment for magazines is.', 'the time when London Fashion Week took place.'],
  'Mencionar un tema no es informarlo. Pregúntate qué dato podrías anotar después de leer: ese está de verdad en el texto.', 'publicada', 'modelo', '190c95847d02eb8121c2ee5210f3d69d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('de9d8020-d261-4375-9161-4bcdcd2ae192', 3, 'La primera línea dice que es febrero y que la semana de la moda acaba de terminar: eso sí es un dato concreto que el lector se lleva. Del modelo del momento y de las tendencias solo dice que las revistas hablan de eso, pero nunca cuenta cuáles son.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '58b2a583-05b3-4d34-9a7d-24cb6dcbaf16', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'f5575687-b32e-46e0-ad64-7b8c9ce7bada', 'Parte 5 · Comprensión de lectura',
  'At the beginning, she thought that if she dressed for success',
  array['she would be able to understand her troubles.', 'she could be a model in fashion shows.', 'her workmates would admire her.', 'her picture could appear on magazines.'],
  'Colleagues y workmates significan lo mismo. Cuando una opción cambia la palabra, comprueba que no cambie la idea.', 'publicada', 'modelo', '2b7239c66922bc42d9ee73535d5c9ce7';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('58b2a583-05b3-4d34-9a7d-24cb6dcbaf16', 2, 'Al comienzo se imagina que los colegas estarán orgullosos de ella y que conseguirá un mejor puesto: eso es la admiración de sus compañeros de trabajo. Sus problemas iban a desaparecer, no a entenderse, y nunca pensó en ser modelo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '878b72fb-0a24-41a0-8632-00c44773d67d', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'f5575687-b32e-46e0-ad64-7b8c9ce7bada', 'Parte 5 · Comprensión de lectura',
  'The writer''s opinion changed because',
  array['nothing good happened when she wore the same clothing.', 'she realized that she couldn''t feel or look better.', 'she had only dark color clothing to wear.', 'her clothes looked really miserable.'],
  'Busca el momento exacto en que el texto cambia de dirección. Aquí es «I realize that I wore exactly the same clothing».', 'publicada', 'modelo', '61c3519614947dc3c02a68afa3656a36';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('878b72fb-0a24-41a0-8632-00c44773d67d', 0, 'El giro llega frente al espejo: se da cuenta de que llevaba la misma ropa que dos días atrás, el día en que perdió el bolso y peleó con su pareja. La misma ropa no le trajo un buen día, y por eso deja de creer en la fórmula.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '25d241cc-b1b3-4a98-a878-4ae120b440e2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  'f5575687-b32e-46e0-ad64-7b8c9ce7bada', 'Parte 5 · Comprensión de lectura',
  'Catherine could add to her letter the following:',
  array['You do not have to worry as long as you have shorts and tights to put on because they are basic pieces of clothing.', 'If you want to be satisfied with life, you should get dressed differently from the models of the London Fashion Week!', 'It does not matter what you wear; what is important is how you feel and the thoughts you have about yourself!', 'Do not wear dark colors because you can get depressed. Buy colorful clothing, which makes you feel better.'],
  'Para «could add», busca la opción que continúe la conclusión del autor, no la que retome el tema del principio.', 'publicada', 'modelo', 'e27041c36d04a4bbaf4d278ef8e244dc';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('25d241cc-b1b3-4a98-a878-4ae120b440e2', 2, 'Su conclusión es que el éxito es un estado mental, y esa frase la repite en otras palabras: no importa qué te pongas, importa cómo te sientes. Las otras tres siguen dando consejos de ropa, que es justo lo que ella deja de hacer.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'dac4e86f-2a70-4f11-afd2-e082ea511e61', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3564ab75-9681-478f-8e08-b570c502e074', 'Parte 5 · Comprensión de lectura',
  'What is the author trying to do in this text?',
  array['revise how successful people develop effective communication.', 'help people become successful with different communication skills.', 'suggest how to develop better relationships with communication skills.', 'point at emotions that help improve effective communication.'],
  'Fíjate a quién le habla el texto. Si te da instrucciones a ti, la intención es ayudarte, no describir a terceros.', 'publicada', 'modelo', 'c6111f5994463d28a876beaa8507c53a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dac4e86f-2a70-4f11-afd2-e082ea511e61', 1, 'El texto abre diciendo que el 85 % del éxito depende de saber comunicarse, sigue con que cualquiera puede desarrollar esas habilidades y termina enumerando lo que se gana. Es una guía para que el lector logre el éxito, no una revisión de lo que hacen otros.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'bbde8e4e-9b0e-428c-be79-b5caeaa91e60', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3564ab75-9681-478f-8e08-b570c502e074', 'Parte 5 · Comprensión de lectura',
  'In this article you learn',
  array['to behave when you are listening to someone.', 'how smart people can communicate effectively.', 'facts about the kind of people who are better at communicating.', 'to control the way you reply when you are explaining your point of view.'],
  'Cuando un párrafo entero está en imperativo (don’t, listen, make sure), ahí está lo que el texto te enseña a hacer.', 'publicada', 'modelo', '93e3e36b0fdd983c01efc601d65e2eaa';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('bbde8e4e-9b0e-428c-be79-b5caeaa91e60', 0, 'El tercer párrafo es una lista de instrucciones para el momento de escuchar: no pienses en lo que vas a decir, escucha cada palabra, responde con naturalidad y pregunta cuando no entiendas. Eso es cómo comportarse al escuchar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '2f240861-8d0b-4e78-b419-f6d6a44d6434', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3564ab75-9681-478f-8e08-b570c502e074', 'Parte 5 · Comprensión de lectura',
  'What would be one advantage of taking into account others'' opinions?',
  array['It''s possible to understand people and their mistakes.', 'You can recommend helpful options to individual benefits.', 'It''s possible to find out information from people''s body language.', 'You can build a broader contact with your colleagues.'],
  'Cuidado con las opciones que repiten una palabra del texto usada en otro sentido. Verifica la frase completa donde aparece.', 'publicada', 'modelo', 'c2f1d024f42bf41325ca10a347aea87f';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2f240861-8d0b-4e78-b419-f6d6a44d6434', 3, 'El texto dice que esa conexión mejora el trabajo en equipo y ayuda a construir mejores relaciones en la casa y en el trabajo: eso es ampliar el contacto con quienes te rodean. La palabra «mistake» aparece, pero referida a errores de la comunicación, no a errores de las personas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1b70c3fb-a2b6-4b38-98e1-b21f121d59fa', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3564ab75-9681-478f-8e08-b570c502e074', 'Parte 5 · Comprensión de lectura',
  'When people feel they are heard, they are more likely to',
  array['be certain of bringing problems to light.', 'think more about what they have to say.', 'lead the conversation and listen to the other.', 'deal with new challenges to avoid disagreement.'],
  'Relaciona la pregunta con el efecto que el texto atribuye a escuchar bien, no con lo que hace quien escucha.', 'publicada', 'modelo', 'a8f23a842dc2247093c0c664be2de893';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1b70c3fb-a2b6-4b38-98e1-b21f121d59fa', 0, 'El último párrafo dice que harás que la gente se sienta más segura para expresar lo que piensa: quien se siente escuchado se anima a sacar a la luz lo que le preocupa. Pensar en lo que uno va a decir es justo lo que el texto pide evitar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3367451c-91c1-4fa3-a628-adc497d6ec0a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3564ab75-9681-478f-8e08-b570c502e074', 'Parte 5 · Comprensión de lectura',
  'A conference announcement on effective communication would be:',
  array['«Personal development conference» — It will provide opportunities to achieve communication skills. Audience: team leaders.', '«Gain an active role when communicating» — You will reach a high performance in your day-to-day communication. Audience: general public.', '«Manage your body language» — You will express your thoughts and complaints positively. Audience: experts.', '«Tips to succeed in your job» — You will receive support in teamwork management. Audience: professionals.'],
  'En las preguntas con avisos, compara el público destinatario: el texto ya te dijo para quién es.', 'publicada', 'modelo', '89b1ee99db0ecaeb2dc9684688d767e0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3367451c-91c1-4fa3-a628-adc497d6ec0a', 1, 'El texto insiste en que cualquiera puede desarrollar estas habilidades y habla de la comunicación del día a día, en la casa y en el trabajo. El anuncio dirigido al público general y a la comunicación cotidiana es el único que respeta las dos ideas. Los otros tres limitan el público a líderes, expertos o profesionales.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e8197035-bf3a-4b38-98fb-2f8506a7e904', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3d9cbbe8-0a3d-4c26-a8a5-2ec8aae8dd11', 'Parte 5 · Comprensión de lectura',
  'One of the activities people do in the festival is to',
  array['visit their families.', 'play without their kids.', 'get a new job.'],
  'Ojo con las opciones que invierten un detalle: «with their children» no es lo mismo que «without their kids».', 'publicada', 'modelo', '9edc98738f480dc3279b36931de04fb3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e8197035-bf3a-4b38-98fb-2f8506a7e904', 0, 'Quienes trabajan en la capital vuelven a su pueblo con sus hijos y pasan tiempo con sus padres, a quienes no veían hace mucho: eso es visitar a la familia. Van con los niños, no sin ellos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '85d76fd5-8326-4cfb-bb4c-37b53eec92ba', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3d9cbbe8-0a3d-4c26-a8a5-2ec8aae8dd11', 'Parte 5 · Comprensión de lectura',
  'The festival is special because',
  array['It''s only for workers.', 'It takes lots of time.', 'It''s for good luck.'],
  'Cuando una costumbre busca un buen año o alejar problemas, en inglés eso se resume como good luck.', 'publicada', 'modelo', 'e9d562453195a1e0f34d302e2ebf4d8d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('85d76fd5-8326-4cfb-bb4c-37b53eec92ba', 2, 'La gente se echa agua en la cabeza para tener un año excelente, con dinero y sin problemas: eso es pedir buena suerte. El texto aclara además que está abierto a todo el mundo, no solo a los trabajadores.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3a35f6b4-94cb-4bd6-b5f2-6b78ca63e69a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3d9cbbe8-0a3d-4c26-a8a5-2ec8aae8dd11', 'Parte 5 · Comprensión de lectura',
  'The festival has become',
  array['a famous market.', 'a place to cook.', 'a fun competition.'],
  'La palabra «become» pide un cambio. Busca el párrafo que empiece con «However, the festival has changed».', 'publicada', 'modelo', '096b60250efda2d7f3d41e42ec2ce51c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3a35f6b4-94cb-4bd6-b5f2-6b78ca63e69a', 2, 'El texto dice que ahora la gente arma equipos para lanzarse agua en un partido y elegir un ganador: equipos, partido y ganador describen una competencia. Que vendan juguetes de agua no lo convierte en un mercado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1c886d3d-282b-47e2-ba2e-6c73b1ad3bef', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3d9cbbe8-0a3d-4c26-a8a5-2ec8aae8dd11', 'Parte 5 · Comprensión de lectura',
  'What should people bring from home?',
  array['uniforms', 'bowls', 'puzzles'],
  'Cups y bowls son recipientes de cocina. Cuando no aparezca la palabra exacta, busca la de la misma familia.', 'publicada', 'modelo', '0adb426d4a89d95d86a9400f638fe776';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1c886d3d-282b-47e2-ba2e-6c73b1ad3bef', 1, 'El texto dice que llevan vasos de distintos tamaños desde sus cocinas para lanzar agua: son recipientes de cocina. Uniformes no, porque justo aclara que los estudiantes no usan su ropa habitual del colegio.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '79323ac0-eebe-4a75-a0c3-61ebdf564233', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '3d9cbbe8-0a3d-4c26-a8a5-2ec8aae8dd11', 'Parte 5 · Comprensión de lectura',
  'What is needed for the festival?',
  array['a bathing suit', 'an umbrella', 'a pair of sunglasses'],
  'Si el texto describe una función («protect your eyes»), busca el objeto que la cumple, aunque no lo nombre.', 'publicada', 'modelo', '95020769798e668feb7cb6ba41572bef';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('79323ac0-eebe-4a75-a0c3-61ebdf564233', 2, 'Pide usar algo que proteja los ojos del sol y del agua, y eso son las gafas. El paraguas sobra en un festival donde el punto es mojarse, y el vestido de baño no se menciona.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3dfe4d4e-fecc-43ce-a23d-9ac5dbb59561', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '1d2e1018-f095-4cbc-8daf-9d48147994ce', 'Parte 5 · Comprensión de lectura',
  'What is the purpose of the writer in this article?',
  array['to describe a suitable exercise routine to do a good workout.', 'to provide several recipes to be used to improve our meals.', 'to inform about the awful effects of certain dangerous exercise routines.', 'to explain that being in good shape doesn''t mean you won''t need medicine.'],
  'Si una misma idea aparece en tres párrafos distintos, esa es la intención del autor.', 'publicada', 'modelo', 'd97ec90359c304d61019d70573c75cd1';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3dfe4d4e-fecc-43ce-a23d-9ac5dbb59561', 3, 'La idea que el autor repite es que estar en forma no garantiza estar sano: se puede ser fuerte por fuera y estar enfermo por dentro, y el ejercicio no da una salud perfecta. Nunca propone una rutina ni da recetas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3d471031-3269-447f-9e5d-b495b8b22ec5', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '1d2e1018-f095-4cbc-8daf-9d48147994ce', 'Parte 5 · Comprensión de lectura',
  'What can the reader discover in the article?',
  array['Too much training may produce trouble in your body.', 'Working out prevents you from being healthy.', 'how to avoid body pains during an exercise program.', 'when to take advantage of a good training plan.'],
  'Distingue «demasiado ejercicio hace daño» de «el ejercicio hace daño». La segunda es una exageración que el texto no sostiene.', 'publicada', 'modelo', 'd409c5fedc0591c8a9707afeaa2732d5';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3d471031-3269-447f-9e5d-b495b8b22ec5', 0, 'El cierre dice que los extremos en el ejercicio pueden destruir la salud y que entrenar demasiado reduce los beneficios. El texto no dice que hacer ejercicio impida estar sano: al contrario, afirma que aumenta las probabilidades de estarlo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '395175a3-8401-441a-b89c-a03c0c9d1a93', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '1d2e1018-f095-4cbc-8daf-9d48147994ce', 'Parte 5 · Comprensión de lectura',
  'Based on Dr. Smith''s words in paragraph 1, we can imagine that',
  array['the possibility to achieve a gorgeous body is exciting.', 'the solution to curing illnesses is being strong.', 'a healthy shape might make us good-looking people.', 'a person who doesn''t look fit can also be healthy.'],
  'Cuando el texto separa dos cosas que solemos unir, la conclusión suele ser que una puede darse sin la otra.', 'publicada', 'modelo', 'f2c30cb8a56d39335fb9e20dbfc726f3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('395175a3-8401-441a-b89c-a03c0c9d1a93', 3, 'Smith dice que verse en forma por fuera no garantiza estar sano por dentro: apariencia y salud van por caminos distintos. Si eso es cierto, también funciona al revés, y alguien que no se ve atlético puede estar perfectamente sano.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '5154db2e-54b0-4df7-801d-9e68e5407b9f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '1d2e1018-f095-4cbc-8daf-9d48147994ce', 'Parte 5 · Comprensión de lectura',
  'What does Ms. Jackson communicate about fitness?',
  array['Exercise performance improves as you make it a habit.', 'The more weight you lift the fewer illnesses you will get.', 'A complicated environment increases your stress.', 'Proper eating is the key to become stronger.'],
  'Cuando la pregunta nombra a una persona, responde solo con lo que dice esa persona entre comillas.', 'publicada', 'modelo', '27b6001b53a00543fdc9e7b349516268';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5154db2e-54b0-4df7-801d-9e68e5407b9f', 0, 'Jackson define el estado físico como la costumbre del cuerpo al ejercicio: si levantas un peso, la próxima vez lo manejas mejor. Eso es mejorar por repetición, es decir, por hábito. Lo de la dieta y el ambiente lo menciona al hablar de salud, no de fitness.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1251d5da-1c2f-4869-86bc-ffbd02798ab1', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '1d2e1018-f095-4cbc-8daf-9d48147994ce', 'Parte 5 · Comprensión de lectura',
  'Which sign in a gym agrees with Dr. Perry''s ideas?',
  array['«Heroes eat more to be as strong as a wooden wall and exercise more to be healthier. Go for it!»', '«Remember to support your exercise routine with the perfect diet for you. Visit our nutritionist regularly.»', '«Get rid of stress with our new routine. Ask our trainers how you can benefit from it now.»', '«Being unfit makes you suffer. Thin people are likely to look unhealthy. Work out hard.»'],
  'Compara cada aviso con la última frase del texto: los cierres suelen condensar la tesis del autor.', 'publicada', 'modelo', '1a3839b77311f8bc8a83f161761b2e85';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1251d5da-1c2f-4869-86bc-ffbd02798ab1', 1, 'La última frase del texto dice que el ejercicio siempre necesita una dieta bien planeada para que el cuerpo aproveche al máximo: ese aviso dice exactamente eso. Los que invitan a comer más y entrenar más chocan con la advertencia sobre los extremos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e702b09f-be2f-4817-8381-72ab7640baf6', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '5653dc9d-3303-4352-bf74-9bc36b55504f', 'Parte 5 · Comprensión de lectura',
  'If you follow the writer''s tips, you could',
  array['go to more touristic areas.', 'pay more money for hotels.', 'have more vacations.'],
  'Los consejos siempre anuncian su propósito antes de la lista. Lee esa frase inicial: ahí está la respuesta.', 'publicada', 'modelo', 'c878c224721d2bff8182483ad8a42edf';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e702b09f-be2f-4817-8381-72ab7640baf6', 0, 'La introducción anuncia el objetivo de los consejos: gastar menos en hoteles y tener más tiempo para visitar otros lugares del viaje. Más lugares visitados es más zonas turísticas; pagar más es justo lo contrario de lo que promete.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '98e5dd4c-5f71-4984-be0e-8514157426f7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '5653dc9d-3303-4352-bf74-9bc36b55504f', 'Parte 5 · Comprensión de lectura',
  'Internet sites like Kayak.com are different from hotel websites because they',
  array['let you book hotels faster.', 'show you various hotels.', 'choose your hotel.'],
  'Comparar no es decidir. Si el texto dice que tú escoges, descarta la opción donde escoge la página.', 'publicada', 'modelo', '08753ab055e3dec0389b8f112b19b64b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('98e5dd4c-5f71-4984-be0e-8514157426f7', 1, 'El texto los propone en vez de entrar a la página de cada hotel, porque muestran las diferencias entre varios de una sola vez. Comparan, pero la elección sigue siendo tuya: dicen «so you can get the best one».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '42e27b27-a20c-4193-8a4b-2a3800c96953', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '5653dc9d-3303-4352-bf74-9bc36b55504f', 'Parte 5 · Comprensión de lectura',
  'Web pages like TravelTicker.com help you',
  array['pay online.', 'get a credit card.', 'learn about better services.'],
  'Cuando una opción menciona algo que el texto niega expresamente (aquí, la tarjeta), descártala de inmediato.', 'publicada', 'modelo', 'd0cb9a74874aaa5cd6d009e0c9bb528f';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('42e27b27-a20c-4193-8a4b-2a3800c96953', 2, 'El texto dice que en esas páginas te enteras de hoteles con la misma experiencia a distinto precio y de servicios especiales, como una piscina cubierta. Además aclara que ni siquiera necesitas tarjeta de crédito para consultarlas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1a3f321e-4678-4a31-bb09-5987831c7eee', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '5653dc9d-3303-4352-bf74-9bc36b55504f', 'Parte 5 · Comprensión de lectura',
  'What is the most important reason to contact the hotel?',
  array['to know visitor''s experiences', 'to receive more e-mails', 'to discuss prices'],
  'Separa lo que se consigue en internet de lo que se consigue llamando: el texto asigna una función distinta a cada canal.', 'publicada', 'modelo', '0fb5d0690fea2eba2875a130daf680af';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1a3f321e-4678-4a31-bb09-5987831c7eee', 2, 'El motivo que da el texto para llamar es dar los precios que encontraste en las páginas, por si el hotel quiere hacerte una oferta: eso es negociar el precio. Las opiniones de los huéspedes se consiguen en las páginas web, no llamando.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'cc3ecf40-4b70-4d76-8ef4-edaefeba9880', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '5653dc9d-3303-4352-bf74-9bc36b55504f', 'Parte 5 · Comprensión de lectura',
  'Tourists might pay less when',
  array['it is winter.', 'there are many people.', 'the weather is hot.'],
  'Si el texto dice que los hoteles ganan más con lleno total, entonces el ahorro está donde hay menos gente.', 'publicada', 'modelo', '95788dc1637e04c6568677a83569490d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cc3ecf40-4b70-4d76-8ef4-edaefeba9880', 0, 'El tercer consejo es viajar en invierno para encontrar hoteles casi vacíos y ahorrar también en vuelos. El texto explica que los hoteles ganan más cuando todos van al mismo tiempo, así que mucha gente significa precios altos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'aa2f9915-7792-400c-bd9e-b8b03f4d0cea', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'When did the first plane fly after Clerck''s dream?',
  array['in 1890', 'in 1738', 'in 1848'],
  'Balloon, plane y flying machine no son lo mismo. Si la pregunta dice «plane», descarta las otras dos.', 'publicada', 'modelo', 'b99214d78794b4c7a72847bfd3b88c30';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('aa2f9915-7792-400c-bd9e-b8b03f4d0cea', 2, 'En 1848 John Hartman hizo un modelo de avión capaz de hacer vuelos cortos: es el primer avión que vuela en el relato. Lo de 1738 fue un globo, no un avión, y en 1890 la máquina de Secrest no llegó a despegar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '8f55e389-0f20-4051-b674-073b08aa3262', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'Who made a machine that never could fly?',
  array['John Hartman', 'Samuel Secrest', 'The Irwins'],
  'Rastrea el resultado de cada intento: «it didn’t work» y «it didn’t go up» son las marcas del fracaso.', 'publicada', 'modelo', '9dbc74588427c18dda9dda5c8000246e';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8f55e389-0f20-4051-b674-073b08aa3262', 1, 'Secrest lo intentó dos veces sin resultado y con otro avión tampoco logró levantar vuelo, así que abandonó el proyecto. Hartman sí voló su modelo y los Irwin volaron su globo más de cinco millas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '407730ef-9dbf-4e23-84db-4a0e45a1a2c8', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'Why was Secrest''s project finished?',
  array['flights took little time', 'flights were delayed', 'flights failed'],
  'Cuando hay varias causas seguidas, la que cierra la frase con «so he stopped» es la que responde al «why».', 'publicada', 'modelo', '77062f3dea5fe3ea4aff6f254ff4442c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('407730ef-9dbf-4e23-84db-4a0e45a1a2c8', 2, 'El texto encadena los fracasos: no funcionó, el avión no subió y por eso detuvo el proyecto. Hubo una demora por el mal clima, pero lo que acabó con el proyecto fueron los intentos fallidos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e254e1c6-66cf-4af0-bc75-fb71e6391bc7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'Orville and Nathan were important because they',
  array['started the air age.', 'worked together.', 'knew the desert.'],
  'La expresión «As a result» señala la consecuencia. Ahí suele estar la importancia de un personaje.', 'publicada', 'modelo', '10010fe58a042a9ca9be1e3b101ae02e';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e254e1c6-66cf-4af0-bc75-fb71e6391bc7', 0, 'Después de sus vuelos, el texto concluye que en 1907 comenzó el transporte aéreo: esa consecuencia es lo que los vuelve importantes. Que trabajaran juntos o conocieran el desierto son detalles, no la razón.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4c7034f1-54b7-4d7d-8b70-450e63967a57', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'Passengers were able to travel by air since',
  array['1900.', '1903.', '1907.'],
  'Distingue el primer vuelo del inicio del transporte: son dos fechas distintas y las preguntas suelen jugar con eso.', 'publicada', 'modelo', '2cdc7c322363a24fed7089f59378cb3b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4c7034f1-54b7-4d7d-8b70-450e63967a57', 2, 'El transporte aéreo, que es el que lleva pasajeros, empezó en 1907. En 1903 lo que ocurrió fue el vuelo del Kitty Hawk Flyer, que duró doce segundos y no transportaba a nadie.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6f4dc542-cf26-448f-b4c5-d7143ed8a5dd', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'The Kitty Hawk Flyer flew',
  array['at once.', 'for a short time.', 'many kilometers.'],
  'Doce segundos es un dato. Tradúcelo a la idea que pide la opción: eso es «a short time».', 'publicada', 'modelo', '45d9016fb5500cfc8ab5b3dbe7d1d6be';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6f4dc542-cf26-448f-b4c5-d7143ed8a5dd', 1, 'Se mantuvo en el aire doce segundos, que es muy poco tiempo. Además el texto aclara que lo lograron «after trying many times», así que no fue a la primera, y los mil vuelos posteriores fueron de corta distancia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1fea349c-07de-4e1e-b909-8ecf812f0d83', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-6-lectura'),
  (select id from public.lotes where codigo = '2026-B'),
  '6de6ad7c-9f35-406f-a4e7-ba809605a1bf', 'Parte 5 · Comprensión de lectura',
  'Who was born in The United States?',
  array['Brett', 'Gabriel', 'Mike'],
  'Las nacionalidades vienen pegadas al nombre: American, British, French. Búscalas antes de escoger.', 'publicada', 'modelo', 'd0fd767b8fb03a3c3525417ee3bcc2eb';
